        });

        const containeralumini = document.getElementById('alumni-container');
        const loadMoreBtn = document.getElementById('load-more-btn');
        const itemsPerPage = 30;
        let currentIndex = 0;

        function renderAlumni(startIndex, count) {
            for (let i = startIndex; i < startIndex + count && i < alumniData.length; i++) {
                const alumni = alumniData[i];
                if (alumni.name === "Akash Kumar Sinha") {
                    continue;
                }
                const colDiv = document.createElement('div');
                colDiv.className = 'part';

                const studentImg = document.createElement('img');
                studentImg.src = `<?php echo asset_url(); ?>dit/images/our-placements-new/alumini/${alumni.studentImage}`;
                studentImg.alt = alumni.studentAlt;
                studentImg.className = 'img-fluid';
                studentImg.width = 91;
                studentImg.height = 91;
                studentImg.loading = 'lazy';

                const namePara = document.createElement('p');
                namePara.className = 'name';
                namePara.textContent = alumni.name;

                const professionPara = document.createElement('p');
                professionPara.className = 'profession';
                professionPara.textContent = alumni.profession;

                const bottomSideDiv = document.createElement('div');
                bottomSideDiv.className = 'bottom-side';

                const companyImg = document.createElement('img');
                companyImg.src = `<?php echo asset_url(); ?>dit/images/our-placements-new/alumini/${alumni.companyImage}`;
                companyImg.alt = alumni.companyAlt;
                companyImg.className = 'img-fluid';
                companyImg.width = 200;
                companyImg.height = 50;
                companyImg.style.height = '50px';
                // companyImg.style.maxHeight = '50px';
                companyImg.style.objectFit = 'contain';
                companyImg.loading = 'lazy';

                bottomSideDiv.appendChild(companyImg);

                colDiv.appendChild(studentImg);
                colDiv.appendChild(namePara);
                colDiv.appendChild(professionPara);
                colDiv.appendChild(bottomSideDiv);

                containeralumini.appendChild(colDiv);
            }
        }

        loadMoreBtn.addEventListener('click', () => {
            renderAlumni(currentIndex, itemsPerPage);
            currentIndex += itemsPerPage;

            if (currentIndex >= alumniData.length) {
                loadMoreBtn.style.display = 'none';
            }
        });

        renderAlumni(currentIndex, itemsPerPage);
        currentIndex += itemsPerPage;
    </script>

</body>

</html>